// StreamingSignerStubOption configures a [StreamingSignerStub] at its
// construction.
type StreamingSignerStubOption func(*StreamingSignerStub)

// StreamingSignerStubStrict returns the option that makes an unconfigured
// method fail the test instead of returning its zero value.
func StreamingSignerStubStrict() StreamingSignerStubOption {
	return func(s *StreamingSignerStub) { s.strict = true }
}

// StreamingSignerStubDelegateTo returns the option that passes each call
// to impl. The double still records the call.
func StreamingSignerStubDelegateTo(impl sign.StreamingSigner) StreamingSignerStubOption {
	return func(s *StreamingSignerStub) {
		s.OnNewSignStream.Func(impl.NewSignStream)
		s.OnSign.Func(impl.Sign)
		s.OnKeyID.Func(impl.KeyID)
		s.OnPublicKey.Func(impl.PublicKey)
		s.OnAlgorithm.Func(impl.Algorithm)
		s.OnVerify.Func(impl.Verify)
	}
}

// StreamingSignerStubWithClock returns the option that sets the clock of
// the double to clk. The double takes the latency, the windows of the
// faults and the instants of the calls from clk. A latency on a controlled
// clock costs no real time.
func StreamingSignerStubWithClock(clk assert.Clock) StreamingSignerStubOption {
	return func(s *StreamingSignerStub) { s.group.SetClock(clk) }
}

// StreamingSignerStubWithRandSource returns the option that sets the
// random source of the probabilistic faults to src. A seeded source
// repeats the faults of a run.
func StreamingSignerStubWithRandSource(src rand.Source) StreamingSignerStubOption {
	return func(s *StreamingSignerStub) { s.group.SetRandSource(src) }
}

// StreamingSignerStubBenchMode returns the option that turns the recording
// of calls off. The methods still return their results.
func StreamingSignerStubBenchMode() StreamingSignerStubOption {
	return func(s *StreamingSignerStub) { s.group.BenchMode() }
}

// StreamingSignerStubWithLatency returns the option that makes every
// method sleep d before it returns. Without StreamingSignerStubWithClock,
// d passes in real time.
func StreamingSignerStubWithLatency(d time.Duration) StreamingSignerStubOption {
	return func(s *StreamingSignerStub) { s.group.SetLatency(d) }
}

// StreamingSignerStubFailing returns the option that arms err on each
// method that can fail. Each call of such a method then fails with err.
func StreamingSignerStubFailing(err error) StreamingSignerStubOption {
	return func(s *StreamingSignerStub) {
		s.OnSign.Faults(err, 1)
	}
}

