// StreamingSignerStub is a recording test double of StreamingSigner. Each
// field On<Method> configures its method. An unconfigured method records
// the call and returns the zero values of its results.
type StreamingSignerStub struct {
	OnNewSignStream *StreamingSignerNewSignStreamStub
	// OnSign configures Sign, which Signer declares.
	OnSign *StreamingSignerSignStub
	// OnKeyID configures KeyID, which Verifier declares.
	OnKeyID *StreamingSignerKeyIDStub
	// OnPublicKey configures PublicKey, which Verifier declares.
	OnPublicKey *StreamingSignerPublicKeyStub
	// OnAlgorithm configures Algorithm, which Verifier declares.
	OnAlgorithm *StreamingSignerAlgorithmStub
	// OnVerify configures Verify, which Verifier declares.
	OnVerify *StreamingSignerVerifyStub

	// group contains the stub of each method.
	group  *stub.Group
	strict bool
}

// The compiler checks that StreamingSignerStub implements StreamingSigner.
var _ sign.StreamingSigner = (*StreamingSignerStub)(nil)

// NewStreamingSignerStub returns a double of StreamingSigner that reports
// its failures to tb and applies opts. The double checks the expected
// counts of calls at the end of the test. With a nil tb, the double
// reports nothing.
func NewStreamingSignerStub(tb assert.TB, opts ...StreamingSignerStubOption) *StreamingSignerStub {
	s := &StreamingSignerStub{
		OnNewSignStream: &StreamingSignerNewSignStreamStub{
			MethodStub: stub.NewMethodStub[StreamingSignerNewSignStreamCall](tb, "StreamingSigner.NewSignStream"),
		},
		OnSign: &StreamingSignerSignStub{
			MethodStub: stub.NewMethodStub[StreamingSignerSignCall](tb, "StreamingSigner.Sign"),
		},
		OnKeyID: &StreamingSignerKeyIDStub{
			MethodStub: stub.NewMethodStub[StreamingSignerKeyIDCall](tb, "StreamingSigner.KeyID"),
		},
		OnPublicKey: &StreamingSignerPublicKeyStub{
			MethodStub: stub.NewMethodStub[StreamingSignerPublicKeyCall](tb, "StreamingSigner.PublicKey"),
		},
		OnAlgorithm: &StreamingSignerAlgorithmStub{
			MethodStub: stub.NewMethodStub[StreamingSignerAlgorithmCall](tb, "StreamingSigner.Algorithm"),
		},
		OnVerify: &StreamingSignerVerifyStub{
			MethodStub: stub.NewMethodStub[StreamingSignerVerifyCall](tb, "StreamingSigner.Verify"),
		},
	}
	s.group = stub.NewGroup(
		s.OnNewSignStream.MethodStub,
		s.OnSign.MethodStub,
		s.OnKeyID.MethodStub,
		s.OnPublicKey.MethodStub,
		s.OnAlgorithm.MethodStub,
		s.OnVerify.MethodStub,
	)
	for _, opt := range opts {
		opt(s)
	}
	if s.strict {
		s.group.StrictAll()
	}
	s.group.Bind(tb)
	return s
}

// NewStreamingSignerStubDelayed returns a double whose methods sleep d on
// clk before they return. It applies opts after the clock and the latency.
func NewStreamingSignerStubDelayed(
	tb assert.TB,
	d time.Duration,
	clk assert.Clock,
	opts ...StreamingSignerStubOption,
) *StreamingSignerStub {
	return NewStreamingSignerStub(tb, append([]StreamingSignerStubOption{
		StreamingSignerStubWithClock(clk),
		StreamingSignerStubWithLatency(d),
	}, opts...)...)
}

// NewStreamingSignerStubFailing returns a double on which each call of a
// method that can fail fails with err. It applies opts after the failure.
func NewStreamingSignerStubFailing(tb assert.TB, err error, opts ...StreamingSignerStubOption) *StreamingSignerStub {
	return NewStreamingSignerStub(tb, append([]StreamingSignerStubOption{StreamingSignerStubFailing(err)}, opts...)...)
}

// ResetCalls clears the recorded calls, the counters of the faults and the
// expected counts. It keeps the functions, the fixed results and the faults.
func (s *StreamingSignerStub) ResetCalls() {
	s.group.Reset()
}

