// VerifyStreamVerifyStub configures Verify and records its calls. Verify
// returns no error, so a fault armed through it fails the test.
type VerifyStreamVerifyStub struct {
	*stub.MethodStub[VerifyStreamVerifyCall]

	fn       func([]byte) bool
	fallback *VerifyStreamVerifyReturn
}

// VerifyStreamVerifyReturn contains the fixed results of Verify.
type VerifyStreamVerifyReturn struct {
	Result bool
}

// Returns sets the results of every call of Verify. A function takes
// precedence over them.
func (s *VerifyStreamVerifyStub) Returns(result bool) *VerifyStreamVerifyStub {
	s.fallback = &VerifyStreamVerifyReturn{Result: result}
	return s
}

// Func sets the function that computes the results of Verify from its
// arguments.
