// version of the runtime of doubles.
var _ = stub.CompatV1

// VerifyStreamStubOption configures a [VerifyStreamStub] at its
// construction.
type VerifyStreamStubOption func(*VerifyStreamStub)

// VerifyStreamStubStrict returns the option that makes an unconfigured
// method fail the test instead of returning its zero value.
func VerifyStreamStubStrict() VerifyStreamStubOption {
	return func(s *VerifyStreamStub) { s.strict = true }
}

// VerifyStreamStubDelegateTo returns the option that passes each call to
// impl. The double still records the call.
func VerifyStreamStubDelegateTo(impl sign.VerifyStream) VerifyStreamStubOption {
	return func(s *VerifyStreamStub) {
		s.OnVerify.Func(impl.Verify)
		s.OnWrite.Func(impl.Write)
	}
}

// VerifyStreamStubWithClock returns the option that sets the clock of the
// double to clk. The double takes the latency, the windows of the faults
// and the instants of the calls from clk. A latency on a controlled clock
// costs no real time.
func VerifyStreamStubWithClock(clk assert.Clock) VerifyStreamStubOption {
	return func(s *VerifyStreamStub) { s.group.SetClock(clk) }
}

// VerifyStreamStubWithRandSource returns the option that sets the random
// source of the probabilistic faults to src. A seeded source repeats the
// faults of a run.
func VerifyStreamStubWithRandSource(src rand.Source) VerifyStreamStubOption {
	return func(s *VerifyStreamStub) { s.group.SetRandSource(src) }
}

// VerifyStreamStubBenchMode returns the option that turns the recording of
// calls off. The methods still return their results.
func VerifyStreamStubBenchMode() VerifyStreamStubOption {
	return func(s *VerifyStreamStub) { s.group.BenchMode() }
}

// VerifyStreamStubWithLatency returns the option that makes every method
// sleep d before it returns. Without VerifyStreamStubWithClock, d passes
// in real time.
func VerifyStreamStubWithLatency(d time.Duration) VerifyStreamStubOption {
	return func(s *VerifyStreamStub) { s.group.SetLatency(d) }
}

// VerifyStreamStubFailing returns the option that arms err on each method
// that can fail. Each call of such a method then fails with err.
func VerifyStreamStubFailing(err error) VerifyStreamStubOption {
	return func(s *VerifyStreamStub) {
		s.OnWrite.Faults(err, 1)
	}
}

// WithVerifyStreamVerify returns the option that sets the function of
// Verify.
func WithVerifyStreamVerify(fn func([]byte) bool) VerifyStreamStubOption {
	return func(s *VerifyStreamStub) { s.OnVerify.Func(fn) }
}

// WithVerifyStreamWrite returns the option that sets the function of
// Write.
func WithVerifyStreamWrite(fn func([]byte) (int, error)) VerifyStreamStubOption {
	return func(s *VerifyStreamStub) { s.OnWrite.Func(fn) }
}

// VerifyStreamStub is a recording test double of VerifyStream. Each field
// On<Method> configures its method. An unconfigured method records the
// call and returns the zero values of its results.
type VerifyStreamStub struct {
	OnVerify *VerifyStreamVerifyStub
	// OnWrite configures Write, which Writer declares.
	OnWrite *VerifyStreamWriteStub

	// group contains the stub of each method.
	group  *stub.Group
	strict bool
}

// The compiler checks that VerifyStreamStub implements VerifyStream.
var _ sign.VerifyStream = (*VerifyStreamStub)(nil)

// NewVerifyStreamStub returns a double of VerifyStream that reports its
// failures to tb and applies opts. The double checks the expected counts
// of calls at the end of the test. With a nil tb, the double reports
// nothing.
func NewVerifyStreamStub(tb assert.TB, opts ...VerifyStreamStubOption) *VerifyStreamStub {
	s := &VerifyStreamStub{
		OnVerify: &VerifyStreamVerifyStub{
			MethodStub: stub.NewMethodStub[VerifyStreamVerifyCall](tb, "VerifyStream.Verify"),
		},
		OnWrite: &VerifyStreamWriteStub{
			MethodStub: stub.NewMethodStub[VerifyStreamWriteCall](tb, "VerifyStream.Write"),
		},
	}
	s.group = stub.NewGroup(
		s.OnVerify.MethodStub,
		s.OnWrite.MethodStub,
	)
	for _, opt := range opts {
		opt(s)
	}
	if s.strict {
		s.group.StrictAll()
	}
	s.group.Bind(tb)
	return s
}

// NewVerifyStreamStubDelayed returns a double whose methods sleep d on clk
// before they return. It applies opts after the clock and the latency.
func NewVerifyStreamStubDelayed(
	tb assert.TB,
	d time.Duration,
	clk assert.Clock,
	opts ...VerifyStreamStubOption,
) *VerifyStreamStub {
	return NewVerifyStreamStub(tb, append([]VerifyStreamStubOption{
		VerifyStreamStubWithClock(clk),
		VerifyStreamStubWithLatency(d),
	}, opts...)...)
}

// NewVerifyStreamStubFailing returns a double on which each call of a
// method that can fail fails with err. It applies opts after the failure.
func NewVerifyStreamStubFailing(tb assert.TB, err error, opts ...VerifyStreamStubOption) *VerifyStreamStub {
	return NewVerifyStreamStub(tb, append([]VerifyStreamStubOption{VerifyStreamStubFailing(err)}, opts...)...)
}

